package com.example.guitarmes.process;
import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.util.List; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.test.web.servlet.MockMvc; import org.springframework.test.web.servlet.setup.MockMvcBuilders; import com.example.guitarmes.guitar.GuitarService;
@ExtendWith(MockitoExtension.class) class ProcessViewControllerTest { @Mock ProcessService service; @Mock GuitarService guitarService; @Mock ManufacturingProcessRepository repository; MockMvc mvc;
@BeforeEach void setUp(){mvc=MockMvcBuilders.standaloneSetup(new ProcessViewController(service,guitarService,repository)).build();}
@Test void bulkStart_redirects() throws Exception { when(service.startProcesses(List.of(1L,2L),3L,"Worker")).thenReturn(List.of(new ProcessHistory(),new ProcessHistory())); mvc.perform(post("/processes/bulk/start").param("guitarIds","1","2").param("processId","3").param("workerName","Worker")).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("/guitars/view")).andExpect(flash().attribute("successMessage","2件の工程を一括開始しました。")); }
@Test void bulkEnd_redirects() throws Exception { when(service.endProcesses(List.of(4L,5L))).thenReturn(List.of(new ProcessHistory(),new ProcessHistory())); mvc.perform(post("/processes/bulk/end").param("historyIds","4","5")).andExpect(status().is3xxRedirection()).andExpect(redirectedUrl("/guitars/view")); }
}
